114	  @ViewBuilder private func agentUsageSegment(_ backend: AgentBackend) -> some View {
115	    if backend == .claude, claudeUsageBridge.state == .disabled {
116	      Button("Enable Claude usage…") { confirmingClaudeUsage = true }
117	        .buttonStyle(StatusBarSegmentButtonStyle())
118	        .foregroundStyle(theme.tokens.accent)
119	        .help("Enable the opt-in Claude status-line bridge")
120	        .accessibilityIdentifier("terminal.statusBar.agentUsage.enableClaude")
121	    } else if let snapshot = agentUsage.snapshot(for: backend) {
122	      let label = quotaAccessibilityLabel(snapshot)
123	      ViewThatFits(in: .horizontal) {
124	        quotaFull(snapshot)
125	        quotaCompact(snapshot)
126	      }
127	      .fixedSize(horizontal: true, vertical: false)
128	      .foregroundStyle(quotaTint(snapshot))
129	      .help(label)
130	      .accessibilityElement(children: .ignore)
131	      .accessibilityLabel(label)
132	      .accessibilityIdentifier("terminal.statusBar.agentUsage")
133	    } else {
134	      let isLoading = agentUsage.loading.contains(backend)
135	      HStack(spacing: 4) {
136	        if isLoading { ProgressView().controlSize(.mini) }
137	        Text(
138	          isLoading
139	            ? "Loading \(backend.displayName) usage…" : "\(backend.displayName) usage unavailable")
140	      }
141	      .foregroundStyle(theme.tokens.fgDim)
142	      .help("Waiting for a fresh local \(backend.displayName) quota snapshot")
143	      .accessibilityLabel(
144	        isLoading
145	          ? "Loading \(backend.displayName) quota usage"
146	          : "\(backend.displayName) quota usage unavailable"
147	      )
148	      .accessibilityIdentifier("terminal.statusBar.agentUsage.unavailable")
149	    }
150	  }
151	
152	  private func quotaFull(_ snapshot: AgentQuotaSnapshot) -> some View {
153	    HStack(spacing: 5) {
154	      Text(snapshot.backend.displayName)
155	      ForEach(snapshot.windows) { window in
156	        Text("·")
157	        let used = Int(window.usedPercentage.rounded())
158	        Text(
159	          "\(window.kind.compactLabel) \(used)%"
160	            + (used == 0 ? "" : " \(window.pace(at: Date()).compactDescription)"))
161	      }
162	    }
163	  }
164	
165	  private func quotaCompact(_ snapshot: AgentQuotaSnapshot) -> some View {
166	    HStack(spacing: 5) {
167	      ForEach(snapshot.windows) { window in
168	        Text("\(window.kind.compactLabel) \(Int(window.usedPercentage.rounded()))%")
169	      }
170	    }
171	  }
172	
173	  private func quotaTint(_ snapshot: AgentQuotaSnapshot) -> AnyShapeStyle {
174	    let now = Date()
175	    if snapshot.windows.contains(where: {
176	      $0.usedPercentage >= 90 || $0.pace(at: now).percentagePoints > 15
177	    }) {
178	      return AnyShapeStyle(theme.tokens.failure)
179	    }
180	    if snapshot.windows.contains(where: { $0.pace(at: now).percentagePoints > 5 }) {
181	      return AnyShapeStyle(theme.tokens.warning)
182	    }
183	    return AnyShapeStyle(theme.tokens.fgMuted)
184	  }
185	
186	  private func quotaAccessibilityLabel(_ snapshot: AgentQuotaSnapshot) -> String {
187	    let now = Date()
188	    let windows = snapshot.windows.map { window in
189	      let used = Int(window.usedPercentage.rounded())
190	      let pace = used == 0 ? "" : ", \(window.pace(at: now).accessibilityDescription)"
191	      return
192	        "\(window.kind.compactLabel) quota \(used)% used\(pace), \(window.resetDescription(at: now))"
193	    }
194	    return "\(snapshot.backend.displayName) quota. " + windows.joined(separator: ". ")
195	  }
