197	  // MARK: File path / branch / cwd
198	
199	  /// The open file's repo-relative path (issue #136) — the pane's identity, which the tab chip can't
200	  /// carry (it shows only the basename, so two `user.rb` tabs read the same). Tooltip resolves it
201	  /// absolutely against the workroom directory.
202	  ///
203	  /// Two modifiers here are decisions, not defaults:
204	  ///
205	  /// - `.head`, unlike the `.middle` its neighbours use. A repo-relative path's discriminating part
206	  ///   is its TAIL: middle-truncating `app/models/user.rb` and `app/views/user.rb` elides exactly the
207	  ///   component that tells them apart, which is the bug this segment exists to fix. Head truncation
208	  ///   drops the shared prefix and keeps the immediate directory plus the filename.
209	  /// - `.layoutPriority(1)`, so the branch yields first when the bar is squeezed. Content panes are
210	  ///   exempt from the pane-width floor (`TerminalSessions.fits` returns true with no surface), so a
211	  ///   split diff pane can be ~198pt wide; without a priority SwiftUI shrinks both labels
212	  ///   proportionally. The path is this pane's identity, while the branch is the same on every pane
213	  ///   of the workroom and already shown in the sidebar.
214	  @ViewBuilder private var pathSegment: some View {
215	    if let filePath {
216	      Label {
217	        Text(filePath).truncationMode(.head)
218	      } icon: {
219	        Image(systemName: "doc")
220	      }
221	      .labelStyle(.titleAndIcon)
222	      .layoutPriority(1)
223	      .help((target.path as NSString).appendingPathComponent(filePath))
224	      .accessibilityLabel("File \(filePath)")
225	      .accessibilityIdentifier("terminal.statusBar.path")
226	    }
227	  }
228	
229	  @ViewBuilder private var branchSegment: some View {
230	    if let branch = store.branchLabel(for: target) {
231	      Label {
232	        Text(branch).truncationMode(.middle)
233	      } icon: {
234	        Image(systemName: "arrow.triangle.branch")
235	      }
236	      .labelStyle(.titleAndIcon)
237	      .help("Current branch / bookmark")
238	      .accessibilityLabel("Branch \(branch)")
239	    }
240	  }
241	
242	  /// The pane's cwd, and the two things you want from a path you can see: copy it, or reveal it
243	  /// (issue #143). Clicking drops the menu; the segment carries a hover well so it reads as clickable
244	  /// (the path and branch segments, which do nothing, deliberately don't).
245	  ///
246	  /// A plain `Button` popping an `NSMenu` by hand, NOT a SwiftUI `Menu`. A `Menu`'s dropped list
247	  /// inherits its TRIGGER's width, and this trigger is a whole filesystem path — so two short items
248	  /// rendered in a menu as wide as the pane. An `NSMenu` we pop ourselves sizes to its own items.
249	  /// (`.menuStyle(.borderlessButton)` wouldn't have helped either: it's AppKit-backed, never reports
250	  /// hover, so the well would be impossible.) The label stays squeezable — no `.fixedSize()` — so
251	  /// `.middle` truncation still fires in a narrow split pane.
252	  ///
253	  /// The items are a menu rather than a selectable label because `.textSelection(.enabled)` swallows
254	  /// real mouseDown, which would kill the click this segment now exists to answer.
255	  @ViewBuilder private var cwdSegment: some View {
256	    if let cwd {
257	      Button {
258	        popCwdMenu(cwd)
259	      } label: {
260	        Label {
261	          Text(Self.abbreviate(cwd)).truncationMode(.middle)
262	        } icon: {
263	          Image(systemName: "folder")
264	        }
265	        .labelStyle(.titleAndIcon)
266	        // Explicit, not inherited: a `Button`'s label doesn't pick up the bar's ambient
267	        // `foregroundStyle`, so without this the segment reads brighter than its neighbours.
268	        .foregroundStyle(theme.tokens.fgMuted)
269	      }
270	      .buttonStyle(StatusBarSegmentButtonStyle())
271	      .background(MenuAnchor(view: $cwdMenuAnchor))
272	      .help(cwd)
273	      .accessibilityLabel("Working directory \(cwd)")
274	      .accessibilityIdentifier("terminal.statusBar.cwd")
275	    }
276	  }
277	
278	  private func popCwdMenu(_ cwd: String) {
279	    let menu = NSMenu()
280	    menu.addItem(
281	      ClosureMenuItem(title: "Copy to Clipboard") {
282	        NSPasteboard.general.clearContents()
283	        NSPasteboard.general.setString(cwd, forType: .string)
284	      })
285	    // `activateFileViewerSelecting`, matching the wording and the File menu's own "Reveal in Finder"
286	    // (which reveals the selected target's directory the same way): the directory comes up selected in
287	    // its parent. `NSWorkspace.open` would open the folder's own window instead — a different verb
288	    // than the one this item promises.
289	    menu.addItem(
290	      ClosureMenuItem(title: "Reveal in Finder") {
291	        NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: cwd)])
292	      })
293	    // At the cursor, like a context menu — but popped out of a real view rather than the tempting
294	    // `at: NSEvent.mouseLocation, in: nil` (screen coordinates, no anchor needed). That form does
295	    // nothing at all when the click is synthesized: `StatusBarCwdUITests` clicked the segment and no
296	    // menu ever appeared. Anchored to a view it opens either way, so the cursor's screen point is
297	    // converted into the anchor's own coordinates instead.
298	    if let anchor = cwdMenuAnchor, let window = anchor.window {
299	      let inWindow = window.convertPoint(fromScreen: NSEvent.mouseLocation)
300	      menu.popUp(positioning: nil, at: anchor.convert(inWindow, from: nil), in: anchor)
301	    } else {
302	      menu.popUp(positioning: nil, at: NSEvent.mouseLocation, in: nil)
303	    }
304	  }
305	
306	  /// `~`-abbreviate a home-relative path; leave others untouched. Truncation is left to the label.
307	  static func abbreviate(_ path: String) -> String {
308	    let home = NSHomeDirectory()
309	    if path == home { return "~" }
310	    if path.hasPrefix(home + "/") { return "~" + path.dropFirst(home.count) }
311	    return path
312	  }
