316	  private func runSegment(_ run: RunPresentation) -> some View {
317	    Label {
318	      Text(run.text)
319	    } icon: {
320	      Image(systemName: run.icon)
321	    }
322	    .labelStyle(.titleAndIcon)
323	    .foregroundStyle(run.color ?? AnyShapeStyle(theme.tokens.fgMuted))
324	    .help("Run command: \(run.text)")
