328	  private struct RunPresentation {
329	    let icon: String
330	    let text: String
331	    /// A tint for a notable state (running/failed); nil inherits the bar's muted foreground.
332	    let color: AnyShapeStyle?
333	  }
334	
335	  private var runStatePresentation: RunPresentation? {
336	    guard let state = store.runStates[target.id] else { return nil }
337	    switch state {
338	    case .armed:
339	      return nil
340	    case .running:
341	      return RunPresentation(
342	        icon: "play.fill", text: "Running", color: AnyShapeStyle(theme.tokens.accent))
343	    case .restarting:
344	      return RunPresentation(
345	        icon: "arrow.clockwise", text: "Restarting", color: AnyShapeStyle(theme.tokens.warning))
346	    case .stopped:
347	      switch store.runOutcomes[target.id] {
348	      case .exited(let code) where code != 0:
349	        return RunPresentation(
350	          icon: "xmark.octagon.fill", text: "Failed (exit \(code))",
351	          color: AnyShapeStyle(theme.tokens.failure))
352	      case .exited:
353	        return RunPresentation(icon: "checkmark.circle", text: "Exited", color: nil)
354	      case .failedToStart:
355	        return RunPresentation(
356	          icon: "xmark.octagon.fill", text: "Failed to start",
357	          color: AnyShapeStyle(theme.tokens.failure))
358	      case .stoppedByUser, .none:
359	        return RunPresentation(icon: "stop.fill", text: "Stopped", color: nil)
360	      }
361	    }
362	  }
