364	  // MARK: Diagnosis
365	
366	  private func diagnosisSegment(_ bannerState: AgentBannerState) -> some View {
367	    let model = AgentBannerViewModel(state: bannerState)
368	    let tint = diagnosisTint(model.style)
369	    return Button {
370	      showingDiagnosis.toggle()
371	    } label: {
372	      HStack(spacing: 4) {
373	        diagnosisIcon(model.style)
374	        Text(model.headline).truncationMode(.tail).frame(maxWidth: 220, alignment: .leading)
375	      }
376	      // A diagnosis means a command FAILED — colour it red on any tab (not only the run tab's run
377	      // state), so a failure reads red everywhere.
378	      .foregroundStyle(tint)
379	    }
380	    .buttonStyle(.plain)
381	    .help("Show the agent's diagnosis")
382	    .accessibilityLabel("Diagnosis: \(model.headline)")
383	    .accessibilityIdentifier("terminal.statusBar.diagnosis")
384	    .popover(isPresented: $showingDiagnosis, arrowEdge: .bottom) {
385	      TerminalAgentBanner(
386	        state: bannerState,
387	        onDiagnose: { agentManager.diagnose(tab: tabID, target: target.id) },
388	        onInsertFix: { fix in
389	          state?.view.sendText(fix)
390	          showingDiagnosis = false
391	        },
392	        onInvestigate: {
393	          _ = store.startInvestigate(bannerState: bannerState, target: target, surface: state?.view)
394	          agentManager.dismiss(tab: tabID)
395	          showingDiagnosis = false
396	        },
397	        onDismiss: {
398	          agentManager.dismiss(tab: tabID)
399	          showingDiagnosis = false
400	        }
401	      )
402	      .frame(width: 380)
403	    }
404	  }
405	
406	  /// Foreground for the diagnosis indicator: red for the command-failure states (a diagnosis exists
407	  /// because a command failed), muted for the transient/neutral ones.
408	  private func diagnosisTint(_ style: AgentBannerViewModel.Style) -> AnyShapeStyle {
409	    switch style {
410	    case .ready, .awaiting, .failure: return AnyShapeStyle(theme.tokens.failure)
411	    case .loading, .remote: return AnyShapeStyle(theme.tokens.fgMuted)
412	    }
413	  }
414	
415	  @ViewBuilder private func diagnosisIcon(_ style: AgentBannerViewModel.Style) -> some View {
416	    switch style {
417	    case .loading:
418	      ProgressView().controlSize(.mini)
419	    case .ready:
420	      Image(systemName: "sparkles")
421	    case .failure:
422	      Image(systemName: "exclamationmark.triangle.fill")
423	    case .awaiting:
424	      Image(systemName: "questionmark.circle")
425	    case .remote:
426	      Image(systemName: "network")
427	    }
428	  }
429	}
