431	/// An invisible AppKit view, laid out behind the cwd segment and handed back through a binding, so
432	/// `NSMenu.popUp(positioning:at:in:)` has a view to pop out of (issue #143) — the view-less,
433	/// screen-coordinate form of that call silently does nothing for a synthesized click.
434	///
435	/// `hitTest` returns nil so the anchor can never take the click that pops the menu, or the hover that
436	/// fills the well, from the `Button` in front of it.
437	private struct MenuAnchor: NSViewRepresentable {
438	  final class AnchorView: NSView {
439	    override func hitTest(_ point: NSPoint) -> NSView? { nil }
440	  }
441	
442	  @Binding var view: NSView?
443	
444	  func makeNSView(context: Context) -> AnchorView {
445	    let anchor = AnchorView()
446	    // Async: assigning to `@State` during `makeNSView` mutates state mid-update.
447	    DispatchQueue.main.async { view = anchor }
448	    return anchor
449	  }
450	
451	  func updateNSView(_ nsView: AnchorView, context: Context) {}
452	}
