454	/// `NSMenuItem` takes an ObjC target/action, and both cwd actions are closures.
455	private final class ClosureMenuItem: NSMenuItem {
456	  private let handler: () -> Void
457	
458	  init(title: String, handler: @escaping () -> Void) {
459	    self.handler = handler
460	    super.init(title: title, action: #selector(fire), keyEquivalent: "")
461	    target = self
462	  }
463	
464	  @available(*, unavailable)
465	  required init(coder: NSCoder) { fatalError("ClosureMenuItem is built in code, never unarchived") }
466	
467	  @objc private func fire() { handler() }
468	}
469	
470	/// Hover well for the status bar's one clickable segment, the cwd (issue #143).
471	///
472	/// The well is a **negatively inset background**, not padding around the label. The cwd shares the
473	/// bar's leading slot with the file path (a terminal has no path, a content pane has no cwd), so
474	/// padding it would put the `folder` glyph 5pt right of where a file pane's `doc` glyph lands — the
475	/// same bar would shift its leading edge depending on which pane you looked at. Negative insets bleed
476	/// the fill outside the label's bounds and leave the layout, and that alignment, untouched.
477	///
478	/// Opacity is animated, never the view tree: an implicit tree animation interpolates a glyph's 1pt
479	/// pixel re-round into a visible slide (see `ToolbarIconButtonStyle`).
480	private struct StatusBarSegmentButtonStyle: ButtonStyle {
481	  func makeBody(configuration: Configuration) -> some View {
482	    HoverWell(configuration: configuration)
483	  }
484	
485	  private struct HoverWell: View {
486	    let configuration: ButtonStyle.Configuration
487	    @State private var hovering = false
488	    @Environment(\.accessibilityReduceMotion) private var reduceMotion
489	
490	    var body: some View {
491	      configuration.label
492	        .background(
493	          RoundedRectangle(cornerRadius: 4)
494	            .fill(
495	              ThemeService.shared.tokens.hover
496	                .opacity(hovering || configuration.isPressed ? 1 : 0)
497	            )
498	            .padding(EdgeInsets(top: -3, leading: -5, bottom: -3, trailing: -5))
499	            .animation(reduceMotion ? nil : .easeOut(duration: 0.12), value: hovering)
500	        )
501	        .contentShape(Rectangle())
502	        .onHover { hovering = $0 }
503	    }
504	  }
505	}
