1	import Darwin
2	import Foundation
3	
4	enum AgentQuotaWindowKind: Equatable, Sendable {
5	  case fiveHour
6	  case weekly
7	  case duration(minutes: Int)
8	
9	  var compactLabel: String {
10	    switch self {
11	    case .fiveHour: return "5h"
12	    case .weekly: return "wk"
13	    case .duration(let minutes):
14	      if minutes.isMultiple(of: 1440) { return "\(minutes / 1440)d" }
15	      if minutes.isMultiple(of: 60) { return "\(minutes / 60)h" }
16	      return "\(minutes)m"
17	    }
18	  }
19	}
20	
21	struct AgentPace: Equatable, Sendable {
22	  /// Percentage points ahead of sustainable use. Negative means under pace.
23	  let percentagePoints: Double
24	
25	  var roundedPoints: Int { Int(percentagePoints.rounded()) }
26	  var isOver: Bool { roundedPoints > 0 }
27	
28	  var compactDescription: String {
29	    if roundedPoints == 0 { return "0%" }
30	    return "\(roundedPoints > 0 ? "+" : "−")\(abs(roundedPoints))%"
31	  }
32	
33	  var accessibilityDescription: String {
34	    if roundedPoints == 0 { return "on sustainable pace" }
35	    if roundedPoints > 0 { return "\(roundedPoints)% in deficit" }
36	    return "\(abs(roundedPoints))% in reserve"
37	  }
38	}
39	
40	struct AgentQuotaWindow: Equatable, Sendable, Identifiable {
41	  let kind: AgentQuotaWindowKind
42	  let usedPercentage: Double
43	  let duration: TimeInterval
44	  let resetsAt: Date
45	
46	  var id: String { kind.compactLabel }
47	
48	  init(
49	    kind: AgentQuotaWindowKind, usedPercentage: Double, duration: TimeInterval, resetsAt: Date
50	  ) {
51	    self.kind = kind
52	    self.usedPercentage = min(max(usedPercentage, 0), 100)
53	    self.duration = duration
54	    self.resetsAt = resetsAt
55	  }
56	
57	  func pace(at now: Date) -> AgentPace {
58	    guard duration > 0 else { return AgentPace(percentagePoints: usedPercentage) }
59	    let startsAt = resetsAt.addingTimeInterval(-duration)
60	    let elapsed = min(max(now.timeIntervalSince(startsAt) / duration, 0), 1) * 100
61	    return AgentPace(percentagePoints: usedPercentage - elapsed)
62	  }
63	
64	  func isFresh(at now: Date) -> Bool { now < resetsAt }
65	
66	  func resetDescription(at now: Date) -> String {
67	    let remaining = resetsAt.timeIntervalSince(now)
68	    guard remaining > 0 else { return "resets now" }
69	
70	    // Round up so a still-fresh window never claims to reset in 0m. The footer deliberately stops at
71	    // minutes: second-level precision adds noise and suggests more certainty than provider snapshots
72	    // offer.
73	    var minutes = Int(ceil(remaining / 60))
74	    let days = minutes / (24 * 60)
75	    minutes %= 24 * 60
76	    let hours = minutes / 60
77	    minutes %= 60
78	
79	    var parts: [String] = []
80	    if days > 0 { parts.append("\(days)d") }
81	    if hours > 0 { parts.append("\(hours)h") }
82	    if minutes > 0 { parts.append("\(minutes)m") }
83	    return "resets in " + parts.joined(separator: ", ")
84	  }
85	}
