99	enum AgentTitleRecognition {
100	  /// Shell integration reports either the actual command line or the provider's own stable title.
101	  /// Only the first executable token is considered; wrappers and prose containing an agent name are
102	  /// deliberately rejected.
103	  static func backend(for title: String?) -> AgentBackend? {
104	    guard let title else { return nil }
105	    let trimmed = title.trimmingCharacters(in: .whitespacesAndNewlines)
106	    guard !trimmed.isEmpty else { return nil }
107	    switch trimmed.lowercased() {
108	    case "claude code": return .claude
109	    case "codex": return .codex
110	    default: break
111	    }
112	
113	    guard let first = trimmed.split(whereSeparator: \.isWhitespace).first else { return nil }
114	    let token = String(first).trimmingCharacters(in: CharacterSet(charactersIn: "\"'"))
115	    // Provider-owned display titles are handled exactly above. Command titles come from the shell
116	    // and use the real, lower-case executable name; keeping this comparison case-sensitive avoids
117	    // treating prose such as "Claude Code setup" as a running agent.
118	    let executable = (token as NSString).lastPathComponent
119	    switch executable {
120	    case "claude": return .claude
121	    case "codex": return .codex
122	    default: return nil
123	    }
124	  }
125	}
