145	enum AgentUsageDecoding {
146	  static let maximumTailBytes = 256 * 1024
147	
148	  static func claude(data: Data, capturedAt: Date, now: Date) -> AgentQuotaSnapshot? {
149	    guard let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
150	      return nil
151	    }
152	    let limits = (root["rate_limits"] as? [String: Any]) ?? root
153	    var windows: [AgentQuotaWindow] = []
154	    if let value = decodeClaudeWindow(
155	      limits["five_hour"], kind: .fiveHour, duration: 5 * 60 * 60)
156	    {
157	      windows.append(value)
158	    }
159	    if let value = decodeClaudeWindow(
160	      limits["seven_day"], kind: .weekly, duration: 7 * 24 * 60 * 60)
161	    {
162	      windows.append(value)
163	    }
164	    return normalized(.claude, windows: windows, capturedAt: capturedAt, now: now)
165	  }
166	
167	  static func codexRollout(data: Data, fileSize: UInt64, modifiedAt: Date, now: Date)
168	    -> AgentQuotaSnapshot?
169	  {
170	    var bytes = data
171	    // A bounded tail can begin halfway through a JSONL record. Drop that fragment.
172	    if fileSize > UInt64(data.count), let newline = bytes.firstIndex(of: 0x0A) {
173	      bytes.removeSubrange(...newline)
174	    }
175	    for rawLine in bytes.split(separator: 0x0A, omittingEmptySubsequences: true).reversed() {
176	      guard
177	        let object = try? JSONSerialization.jsonObject(with: Data(rawLine)) as? [String: Any],
178	        let payload = object["payload"] as? [String: Any],
179	        payload["type"] as? String == "token_count",
180	        let limits = payload["rate_limits"] as? [String: Any]
181	      else { continue }
182	
183	      let capturedAt = (object["timestamp"] as? String).flatMap(parseISO8601) ?? modifiedAt
184	      var windows: [AgentQuotaWindow] = []
185	      for key in ["primary", "secondary"] {
186	        guard let value = limits[key] as? [String: Any],
187	          let minutes = number(value["window_minutes"]).map(Int.init), minutes > 0,
188	          let used = number(value["used_percent"])
189	        else { continue }
190	        let reset: Date?
191	        if let seconds = number(value["resets_at"]) {
192	          reset = Date(timeIntervalSince1970: seconds)
193	        } else if let remaining = number(value["resets_in_seconds"]) {
194	          reset = capturedAt.addingTimeInterval(remaining)
195	        } else {
196	          reset = nil
197	        }
198	        guard let reset else { continue }
199	        windows.append(
200	          AgentQuotaWindow(
201	            kind: kind(for: minutes), usedPercentage: used,
202	            duration: TimeInterval(minutes * 60), resetsAt: reset))
203	      }
204	      if let snapshot = normalized(.codex, windows: windows, capturedAt: capturedAt, now: now) {
205	        return snapshot
206	      }
207	    }
208	    return nil
209	  }
210	
211	  static func readCodexSnapshot(
212	    sessionsRoot: URL, now: Date, maximumTailBytes: Int = maximumTailBytes,
213	    fileManager: FileManager = .default
214	  ) -> AgentQuotaSnapshot? {
215	    guard
216	      let enumerator = fileManager.enumerator(
217	        at: sessionsRoot,
218	        includingPropertiesForKeys: [.isRegularFileKey, .contentModificationDateKey],
219	        options: [.skipsHiddenFiles, .skipsPackageDescendants])
220	    else { return nil }
221	    var candidates: [(URL, Date)] = []
222	    for case let url as URL in enumerator where url.pathExtension == "jsonl" {
223	      guard
224	        let values = try? url.resourceValues(forKeys: [
225	          .isRegularFileKey, .contentModificationDateKey,
226	        ]),
227	        values.isRegularFile == true
228	      else { continue }
229	      candidates.append((url, values.contentModificationDate ?? .distantPast))
230	    }
231	    // A malformed/partially-written newest rollout must not suppress a slightly older valid one.
232	    for (url, modifiedAt) in candidates.sorted(by: { $0.1 > $1.1 }).prefix(12) {
233	      guard let handle = try? FileHandle(forReadingFrom: url) else { continue }
234	      defer { try? handle.close() }
235	      let size = (try? handle.seekToEnd()) ?? 0
236	      let count = min(UInt64(maximumTailBytes), size)
237	      try? handle.seek(toOffset: size - count)
238	      guard let data = try? handle.read(upToCount: Int(count)), !data.isEmpty else { continue }
239	      if let snapshot = codexRollout(
240	        data: data, fileSize: size, modifiedAt: modifiedAt, now: now)
241	      {
242	        return snapshot
243	      }
244	    }
245	    return nil
246	  }
247	
248	  private static func decodeClaudeWindow(
249	    _ raw: Any?, kind: AgentQuotaWindowKind, duration: TimeInterval
250	  ) -> AgentQuotaWindow? {
251	    guard let value = raw as? [String: Any],
252	      let used = number(value["used_percentage"]),
253	      let reset = number(value["resets_at"])
254	    else { return nil }
255	    return AgentQuotaWindow(
256	      kind: kind, usedPercentage: used, duration: duration,
257	      resetsAt: Date(timeIntervalSince1970: reset))
258	  }
259	
260	  private static func normalized(
261	    _ backend: AgentBackend, windows: [AgentQuotaWindow], capturedAt: Date, now: Date
262	  ) -> AgentQuotaSnapshot? {
263	    let fresh = windows.filter { $0.isFresh(at: now) }.sorted { $0.duration < $1.duration }
264	    guard !fresh.isEmpty else { return nil }
265	    return AgentQuotaSnapshot(backend: backend, windows: fresh, capturedAt: capturedAt)
266	  }
267	
268	  private static func kind(for minutes: Int) -> AgentQuotaWindowKind {
269	    switch minutes {
270	    case 300: return .fiveHour
271	    case 10080: return .weekly
272	    default: return .duration(minutes: minutes)
273	    }
274	  }
275	
276	  private static func number(_ value: Any?) -> Double? {
277	    switch value {
278	    case let value as NSNumber: return value.doubleValue
279	    case let value as String: return Double(value)
280	    default: return nil
281	    }
282	  }
283	
284	  private static func parseISO8601(_ value: String) -> Date? {
285	    let formatter = ISO8601DateFormatter()
286	    formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
287	    return formatter.date(from: value) ?? ISO8601DateFormatter().date(from: value)
288	  }
289	}
