292	final class AgentUsageMonitor: ObservableObject {
293	  @Published private(set) var snapshots: [AgentBackend: AgentQuotaSnapshot] = [:]
294	  @Published private(set) var loading: Set<AgentBackend> = []
295	
296	  let codexSessionsURL: URL
297	  let claudeCacheURL: URL
298	  private let now: () -> Date
299	  private var refreshTask: Task<Void, Never>?
300	  private var watches: [DispatchSourceFileSystemObject] = []
301	  private var debounce: DispatchWorkItem?
302	
303	  init(
304	    codexSessionsURL: URL = FileManager.default.homeDirectoryForCurrentUser
305	      .appendingPathComponent(".codex/sessions", isDirectory: true),
306	    claudeCacheURL: URL = ClaudeUsageBridge.defaultDirectory
307	      .appendingPathComponent("claude-rate-limits.json"),
308	    now: @escaping () -> Date = Date.init, startAutomatically: Bool = true
309	  ) {
310	    self.codexSessionsURL = codexSessionsURL
311	    self.claudeCacheURL = claudeCacheURL
312	    self.now = now
313	    if let fixture = UITestFixture.usageSnapshot {
314	      snapshots[fixture.backend] = fixture
315	      return
316	    }
317	    if UITestFixture.usageAgentTitle != nil { return }
318	    if startAutomatically {
319	      refresh()
320	      installWatches()
321	    }
322	  }
323	
324	  deinit {
325	    refreshTask?.cancel()
326	    debounce?.cancel()
327	    for watch in watches { watch.cancel() }
328	  }
329	
330	  func snapshot(for backend: AgentBackend) -> AgentQuotaSnapshot? {
331	    snapshots[backend]?.fresh(at: now())
332	  }
333	
334	  func refresh() {
335	    // A seeded agent title is a model-only UI fixture. Never replace its deterministic snapshot
336	    // (including the intentional unavailable case) by reading the developer's real provider files.
337	    guard UITestFixture.usageAgentTitle == nil else {
338	      loading.removeAll()
339	      return
340	    }
341	    refreshTask?.cancel()
342	    loading = Set(AgentBackend.allCases)
343	    let codexURL = codexSessionsURL
344	    let claudeURL = claudeCacheURL
345	    let current = now()
346	    refreshTask = Task.detached(priority: .utility) {
347	      let codex = AgentUsageDecoding.readCodexSnapshot(sessionsRoot: codexURL, now: current)
348	      let claude: AgentQuotaSnapshot? = {
349	        guard let data = try? Data(contentsOf: claudeURL),
350	          let attrs = try? FileManager.default.attributesOfItem(atPath: claudeURL.path),
351	          let modified = attrs[.modificationDate] as? Date
352	        else { return nil }
353	        return AgentUsageDecoding.claude(data: data, capturedAt: modified, now: current)
354	      }()
355	      guard !Task.isCancelled else { return }
356	      await MainActor.run {
357	        self.snapshots = Dictionary(
358	          uniqueKeysWithValues: [codex, claude].compactMap { $0 }.map { ($0.backend, $0) })
359	        self.loading.removeAll()
360	        self.rebuildWatches()
361	      }
362	    }
363	  }
364	
365	  private func installWatches() { rebuildWatches() }
366	
367	  private func rebuildWatches() {
368	    for watch in watches { watch.cancel() }
369	    watches.removeAll()
370	    var paths = [codexSessionsURL, claudeCacheURL.deletingLastPathComponent()]
371	    if let enumerator = FileManager.default.enumerator(
372	      at: codexSessionsURL, includingPropertiesForKeys: [.isDirectoryKey],
373	      options: [.skipsHiddenFiles, .skipsPackageDescendants])
374	    {
375	      for case let url as URL in enumerator {
376	        if (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) == true {
377	          paths.append(url)
378	        }
379	      }
380	    }
381	    for url in paths where FileManager.default.fileExists(atPath: url.path) {
382	      let descriptor = open(url.path, O_EVTONLY)
383	      guard descriptor >= 0 else { continue }
384	      let source = DispatchSource.makeFileSystemObjectSource(
385	        fileDescriptor: descriptor, eventMask: [.write, .extend, .attrib, .rename, .delete],
386	        queue: .main)
387	      source.setEventHandler { [weak self] in self?.scheduleRefresh() }
388	      source.setCancelHandler { close(descriptor) }
389	      source.resume()
390	      watches.append(source)
391	    }
392	  }
393	
394	  private func scheduleRefresh() {
395	    debounce?.cancel()
396	    let item = DispatchWorkItem { [weak self] in self?.refresh() }
397	    debounce = item
398	    DispatchQueue.main.asyncAfter(deadline: .now() + 0.25, execute: item)
399	  }
400	}
