struct AgentQuotaSnapshot: Equatable, Sendable {
  let backend: AgentBackend
  let windows: [AgentQuotaWindow]
  let capturedAt: Date

  func fresh(at now: Date) -> AgentQuotaSnapshot? {
    let freshWindows = windows.filter { $0.isFresh(at: now) }
    guard !freshWindows.isEmpty else { return nil }
    return AgentQuotaSnapshot(backend: backend, windows: freshWindows, capturedAt: capturedAt)
  }

  /// The shortest-duration window — `windows` is duration-ascending (`AgentUsageDecoding.normalized`
  /// sorts it that way), so this is the finest-grained quota the other windows get projected against
  /// in the detail popover (e.g. a weekly window's "N session quotas left").
  var referenceWindow: AgentQuotaWindow? { windows.first }
}

/// How much longer-window budget remains, expressed against a shorter reference window's current
/// usage rate — e.g. a weekly window "3 session quotas left" against a 5-hour session.
struct AgentQuotaOutlook: Equatable, Sendable {
  /// Nil when the reference window has 0% used — there's no observed rate to project from.
  let estimatedQuotasLeft: Int?
  let windowsUntilReset: Int
}

extension AgentQuotaWindow {
  /// Projects this window's remaining budget in units of `reference`'s current usage rate. Assumes
  /// the reference window's used-so-far percentage holds steady as a per-window consumption rate:
  /// `remaining% / reference.usedPercentage%` estimates how many more windows like it fit before this
  /// one resets.
  func outlook(against reference: AgentQuotaWindow, now: Date) -> AgentQuotaOutlook {
    let remaining = 100 - usedPercentage
    let quotasLeft: Int? =
      reference.usedPercentage > 0 ? max(0, Int(remaining / reference.usedPercentage)) : nil
    let windowsUntilReset = max(0, Int(resetsAt.timeIntervalSince(now) / reference.duration))
    return AgentQuotaOutlook(estimatedQuotasLeft: quotasLeft, windowsUntilReset: windowsUntilReset)
  }
}

