import SwiftUI

/// The detailed usage breakdown opened by clicking the footer's quota segment — one row per window,
/// each showing a progress bar against the reset countdown, plus a pace caption. The compact footer
/// segment stays a glanceable summary; this is where the numbers behind it live.
struct AgentUsageDetailView: View {
  let snapshot: AgentQuotaSnapshot
  let now: Date

  private let theme = ThemeService.shared

  var body: some View {
    VStack(alignment: .leading, spacing: 16) {
      ForEach(snapshot.windows) { window in
        windowRow(window)
      }
    }
    .padding(14)
    .accessibilityElement(children: .contain)
    .accessibilityIdentifier("terminal.statusBar.agentUsage.detail")
  }

  private func windowRow(_ window: AgentQuotaWindow) -> some View {
    let pace = window.pace(at: now)
    // The marker sits at the "sustainable pace" point — where usage would be if it exactly tracked
    // the window's elapsed time — derived from the pace already computed for the compact footer
    // (`usedPercentage - pace.percentagePoints` recovers that elapsed fraction) rather than a second,
    // independently-maintained calculation.
    let paceMarker = min(max(window.usedPercentage - pace.percentagePoints, 0), 100)

    return VStack(alignment: .leading, spacing: 6) {
      HStack(alignment: .firstTextBaseline) {
        Text("\(title(for: window.kind)) \(Int(window.usedPercentage.rounded()))% used")
          .font(.callout)
          .fontWeight(.semibold)
        Spacer(minLength: 12)
        Text(capitalizedResetDescription(window))
          .font(.caption)
          .foregroundStyle(theme.tokens.fgMuted)
      }

      QuotaBar(usedPercentage: window.usedPercentage, markerPercentage: paceMarker)
        .frame(height: 6)

      Text(caption(for: window, pace: pace))
        .font(.caption)
        .foregroundStyle(theme.tokens.fgMuted)
        .fixedSize(horizontal: false, vertical: true)
    }
    .accessibilityElement(children: .combine)
  }

  private func title(for kind: AgentQuotaWindowKind) -> String {
    switch kind {
    case .fiveHour: return "Session"
    case .weekly: return "Weekly"
    case .duration: return "\(kind.compactLabel) window"
    }
  }

  private func capitalizedResetDescription(_ window: AgentQuotaWindow) -> String {
    let raw = window.resetDescription(at: now)
    return raw.prefix(1).uppercased() + raw.dropFirst()
  }

  /// `"9% in reserve · Lasts until reset"`, extended with a longer window's projection against the
  /// snapshot's shortest ("reference") window — `"· Est. 3 session quotas left · 6 windows until
  /// reset"` — when this row isn't that reference window itself.
  private func caption(for window: AgentQuotaWindow, pace: AgentPace) -> String {
    var parts = [pace.accessibilityDescription]
    parts.append(pace.isOver ? "May run out before reset" : "Lasts until reset")

    if let reference = snapshot.referenceWindow, reference.id != window.id {
      let outlook = window.outlook(against: reference, now: now)
      if let quotasLeft = outlook.estimatedQuotasLeft {
        let noun = title(for: reference.kind).lowercased()
        parts.append("Est. \(quotasLeft) \(noun) quota\(quotasLeft == 1 ? "" : "s") left")
      }
      parts.append("\(outlook.windowsUntilReset) windows until reset")
    }

    return parts.joined(separator: " · ")
  }
}

/// A track with a filled portion (usage) and a thin marker (the sustainable-pace point). Deliberately
/// one constant fill tint rather than a severity traffic light — the footer's inline text already
/// carries that (`quotaTint`), and a second, redundant color signal on the bar itself competed with it.
private struct QuotaBar: View {
  let usedPercentage: Double
  let markerPercentage: Double

  private let theme = ThemeService.shared

  var body: some View {
    GeometryReader { geometry in
      let width = geometry.size.width
      ZStack(alignment: .leading) {
        Capsule().fill(theme.tokens.surface)
        Capsule()
          .fill(theme.tokens.accent)
          .frame(width: width * CGFloat(usedPercentage / 100))
        Capsule()
          .fill(theme.tokens.diffAddFg)
          .frame(width: 2)
          .offset(x: max(0, width * CGFloat(markerPercentage / 100) - 1))
      }
    }
  }
}

