func testWindowsUntilResetCountsReferenceWindowsRemaining() {
  let session = AgentQuotaWindow(
    kind: .fiveHour, usedPercentage: 10, duration: 5 * 60 * 60,
    resetsAt: now.addingTimeInterval(4 * 60 * 60 + 3 * 60))
  let weekly = AgentQuotaWindow(
    kind: .weekly, usedPercentage: 63, duration: 7 * 24 * 60 * 60,
    resetsAt: now.addingTimeInterval(24 * 60 * 60 + 9 * 60 * 60))
  let snapshot = AgentQuotaSnapshot(
    backend: .claude, windows: [session, weekly], capturedAt: now)

  XCTAssertEqual(snapshot.referenceWindow, session)
  XCTAssertEqual(weekly.windowsUntilReset(referencing: session, now: now), 6)
}

