/// One concatenated `Text` (not an `HStack` of separate `Text`s, like `quotaCompact` below) because
/// the pace figure needs its own color run inline within a window's segment — only when it's in
/// deficit, so a healthy pace never distracts with color the rest of the bar doesn't have.
private func quotaFull(_ snapshot: AgentQuotaSnapshot) -> Text {
  let now = Date()
  return snapshot.windows.reduce(Text(snapshot.backend.displayName)) { text, window in
    let used = Int(window.usedPercentage.rounded())
    var windowText = Text(" · \(window.kind.compactLabel) \(used)%")
    if used != 0 {
      let pace = window.pace(at: now)
      var paceText = Text(" (\(pace.compactDescription))")
      if pace.isOver { paceText = paceText.foregroundColor(paceColor(pace)) }
      windowText = windowText + paceText
    }
    return text + windowText
  }
}

